#!/usr/bin/env python3
"""Converts shrinkdat.h (XBlast 2.10.4) into packages/sim/src/shrinkdata.ts.

Usage: python3 archeology/gen-shrinkdata.py original/src/xblast-2.10.4/shrinkdat.h
"""
import re
import sys

src = open(sys.argv[1], encoding="latin-1").read()
src = re.sub(r"/\*.*?\*/", "", src, flags=re.S)
tiles = {"BTFree": 0, "BTBurned": 1, "BTBlock": 2, "BTBlockRise": 3, "BTExtra": 4, "BTVoid": 10}

out = [
    "// Generated by archeology/gen-shrinkdata.py from XBlast 2.10.4 shrinkdat.h: do not edit.",
    "// [x, y, offset, level] per block, in shrink order.",
    "",
]
for name, body in re.findall(r"static shri_data (\w+)\[\]\s*=\s*\{(.*?)\};", src, re.S):
    quads = re.findall(r"\{\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(-?\d+)\s*\}", body)
    rows = [f"[{x},{y},{o},{l}]" for x, y, o, l in quads if x != "-1"]
    out.append(f"export const {name}: readonly (readonly number[])[] = [{','.join(rows)}];")
for name, body in re.findall(r"static shri_xoff_data (\w+)\[\]\s*=\s*\{(.*?)\};", src, re.S):
    nums = [n for n in re.findall(r"-?\d+", body)]
    out.append(f"export const {name}: readonly number[] = [{','.join(nums[:-1])}];")
out.append("")
out.append("// [offset, level, block] per step of a style.")
for name, body in re.findall(r"static shri_style2 (\w+)_xx\[\]\s*=\s*\{(.*?)\};", src, re.S):
    triples = re.findall(r"\{\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(\w+|-?\d+)\s*\}", body)
    rows = [f"[{o},{l},{tiles.get(b, b)}]" for o, l, b in triples]
    out.append(f"export const {name}: readonly (readonly number[])[] = [{','.join(rows)}];")
open("packages/sim/src/shrinkdata.ts", "w").write("\n".join(out) + "\n")
print("ok", len(out))
